14	export function convertNanoSecondsToHrTime(nanoseconds: number | bigint): HrTime {
15	  // Handle both number and BigInt inputs
16	  if (typeof nanoseconds === 'bigint') {
17	    // Use BigInt arithmetic to maintain precision
18	    const seconds = Number(nanoseconds / 1_000_000_000n);
19	    const nanos = Number(nanoseconds % 1_000_000_000n);
20	    return [seconds, nanos] as HrTime;
21	  }
22	  // For regular numbers, use standard arithmetic
