/**
 * Configure json-bigint to handle large integers (e.g. nanosecond timestamps)
 * without losing precision. Native BigInt is used for parsed integers that
 * exceed the safe integer range, and BigInt values are serialized as JSON
 * numbers rather than throwing like the native `JSON.stringify`.
 */
const JSONBig = JSONBigInt({
  useNativeBigInt: true,
  alwaysParseAsBig: false,
  storeAsString: false
});

/**
 * Safely stringify a value to JSON, handling values that the native JSON
 * serializer cannot represent (functions, `undefined`, `Error` instances) as
 * well as BigInt values. BigInt support is provided by `JSONBig` so that
 * large integers survive the round-trip without precision loss.
 *
 * @param value The value to stringify
 * @returns JSON string representation of the value
 */
export function safeJsonStringify(value: any): string {
  // MLflow-specific replacer that handles functions, undefined, and errors
  const mlflowReplacer = (_key: string, val: any): any => {
    if (typeof val === 'function') {
      return '[Function]';
    }
    if (val === undefined) {
      return '[Undefined]';
    }

    if (val instanceof Error) {
      return {
        name: val.name,
        message: val.message,
        stack: val.stack
      };
    }

    return val;
  };

  return JSONBig.stringify(value, mlflowReplacer);
}

export { JSONBig };
